import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.BqDA2HS7.js";const k=JSON.parse('{"title":"DSH 接入","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/dsh.md","filePath":"integrations/dsh.md"}'),r={name:"integrations/dsh.md"};function o(n,a,l,h,d,p){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="dsh-接入" tabindex="-1">DSH 接入 <a class="header-anchor" href="#dsh-接入" aria-label="Permalink to &quot;DSH 接入&quot;">​</a></h1><p>DSH 插件连接独立 Python 核心，提供两种模型入口、设置卡片、工具事件与图形展示。 默认本机接入无需单独启动 Router HTTP 服务。</p><h2 id="安装后的检查" tabindex="-1">安装后的检查 <a class="header-anchor" href="#安装后的检查" aria-label="Permalink to &quot;安装后的检查&quot;">​</a></h2><ol><li><code>refractagent --help</code> 在启动 DSH 的同一环境可用。</li><li>生产路由模块启用，<code>validation-tools</code> 保持关闭。</li><li>设置中同时看到 <strong>RefractAgent 规划路由</strong> 和 <strong>RefractAgent 自动路由</strong>。</li><li>会话中看到 <strong>任务 DAG</strong> 与 <strong>路由轨迹</strong> 两个页签。</li><li>原来的 provider、凭证与会话仍在。</li></ol><p>包名为历史兼容保留 <code>dsh-refractrouter-validation</code>，不表示需要启用验收工具。 生产入口通过包主入口加载前端；只启用 <code>/routing</code> 子路径可能不能发现设置与页签。</p><h2 id="首次安装设置草稿" tabindex="-1">首次安装设置草稿 <a class="header-anchor" href="#首次安装设置草稿" aria-label="Permalink to &quot;首次安装设置草稿&quot;">​</a></h2><p>仅供<strong>尚未配置 RefractRouter 的首次安装</strong>。先下载 <a href="/RefractRouter/examples/dsh-first-install.json">dsh-first-install.json</a>，放到工作目录， 阅读里面的初始预算、真实执行关闭状态和空模型池，然后启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --patch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./dsh-first-install.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3080</span></span></code></pre></div><p>随后从 DSH 目录选择自己的模型，登记信任策略与 Judge，按<a href="./../quickstart.html">第一项任务</a> 配置和保存。首次初始化阶段使用同一个补丁与工作目录启动；不要换到新 profile。 <strong>已有 Router 用户直接按原启动方式升级，不加载这个草稿覆盖设置。</strong></p><p>草稿不包含可执行 provider、密钥或虚构价格，零调用诊断在你配置完成前会列出缺项。 不要为了消除提示填入零价格或把所有能力写成支持。</p><h2 id="选择入口与路由模式" tabindex="-1">选择入口与路由模式 <a class="header-anchor" href="#选择入口与路由模式" aria-label="Permalink to &quot;选择入口与路由模式&quot;">​</a></h2><p>规划路由：在模型菜单选择规划入口，再用“路由模式”选择六策略之一。 策略标识由适配器转成内部策略，不作为底层 <code>reasoning_effort</code> 发送。</p><p>自动路由：选择“自动路由（真实执行）”，确认实时配置已启用；模拟入口仍为安装演示， 不能拿模拟文字当成真实回答。</p><h2 id="原生工具与模型历史" tabindex="-1">原生工具与模型历史 <a class="header-anchor" href="#原生工具与模型历史" aria-label="Permalink to &quot;原生工具与模型历史&quot;">​</a></h2><p>规划路由把被接受的模型工具调用原样交回 DSH。工具执行、权限、审批与后台委派由 DSH 管理。 自动路由的宿主工具调用也遵守 DSH 的执行与审批边界。</p><p>每条回复保存实际 provider、模型与 replay 来源；跨模型转换按已验收组合检查。 历史组合未通过时明确阻断，不把旧回复一律标成当前模型，也不删除工具配对来让请求通过。 上下文压缩由 DSH 负责，Router 保留归一化证据与消费事件 ID。</p><h2 id="停止与恢复" tabindex="-1">停止与恢复 <a class="header-anchor" href="#停止与恢复" aria-label="Permalink to &quot;停止与恢复&quot;">​</a></h2><p>使用 DSH 原生取消。插件或核心中断后未确认派发保留待核对状态，不自动重发可能已收费 或产生副作用的操作。重启后读取旧记录；新增配置只影响新任务。</p><h2 id="用-base-url-接入-dsh" tabindex="-1">用 Base URL 接入 DSH <a class="header-anchor" href="#用-base-url-接入-dsh" aria-label="Permalink to &quot;用 Base URL 接入 DSH&quot;">​</a></h2><p>也可不安装插件，在 DSH 配置标准 Chat Completions provider： Base URL <code>http://127.0.0.1:8088/v1</code>，模型 <code>refract/static</code> 等。 这条路径提供标准模型服务，不自动得到插件设置、DAG 页签或原生结构化工具证据。 其能力以网关 <code>/v1/models</code> 与已验收合同为准。</p>`,20)])])}const g=s(r,[["render",o]]);export{k as __pageData,g as default};
